class Solution:
    def minOperations(self, nums: List[int], k: int, queries: List[List[int]]) -> List[int]:
        ans = []
        for l, r in queries:
            md = nums[l] % k
            if any(nums[i] % k != md for i in range(l, r + 1)):
                ans.append(-1); continue
            q = sorted((nums[i] - md) // k for i in range(l, r + 1))
            m = q[len(q) // 2]
            ans.append(sum(abs(x - m) for x in q))
        return ans

