class Solution {
public:
    vector<int> minOperations(vector<int>& nums, int k, vector<vector<int>>& queries) {
        vector<int> ans;
        for (auto& qr : queries) {
            int l = qr[0], r = qr[1], md = nums[l] % k;
            bool ok = true;
            vector<long long> q;
            for (int i = l; i <= r; i++) {
                if (nums[i] % k != md) { ok = false; break; }
                q.push_back((nums[i] - md) / k);
            }
            if (!ok) { ans.push_back(-1); continue; }
            sort(q.begin(), q.end());
            long long m = q[q.size() / 2], cost = 0;
            for (long long x : q) cost += llabs(x - m);
            ans.push_back((int)cost);
        }
        return ans;
    }
};

