public:
    vector<int> minOperations(vector<int>& nums, int k, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> res(n);
        for (int i = 0; i < n; i++) res[i] = nums[i] % k;
        vector<vector<int>> mn, mx;
        mn.push_back(res); mx.push_back(res);
        for (int j = 1; (1 << j) <= n; j++) {
            int h = 1 << (j - 1);
            vector<int> a(n - (1 << j) + 1), b = a;
            for (int i = 0; i + (1 << j) <= n; i++) {
                a[i] = min(mn[j-1][i], mn[j-1][i+h]);
                b[i] = max(mx[j-1][i], mx[j-1][i+h]);
            }
            mn.push_back(a); mx.push_back(b);
        }
        vector<int> vals(n);
        for (int i = 0; i < n; i++) vals[i] = (nums[i] - res[i]) / k;
        vector<int> qs = vals;
        sort(qs.begin(), qs.end()); qs.erase(unique(qs.begin(), qs.end()), qs.end());
        int V = qs.size();
        L = {0}; R = {0}; C = {0}; S = {0};
        vector<int> roots(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int id = lower_bound(qs.begin(), qs.end(), vals[i]) - qs.begin();
            roots[i + 1] = add(roots[i], 0, V - 1, id, vals[i]);
        }
        vector<int> ans;
        for (auto& qr : queries) {
            int l = qr[0], r = qr[1], jg = 31 - __builtin_clz(r - l + 1);
            if (min(mn[jg][l], mn[jg][r - (1 << jg) + 1]) != max(mx[jg][l], mx[jg][r - (1 << jg) + 1])) {
                ans.push_back(-1); continue;
            }
            int A = roots[l], B = roots[r + 1];
            long long tot = C[B] - C[A], stot = S[B] - S[A];
            int kk = (tot + 1) / 2; int lo = 0, hi = V - 1, xa = A, xb = B;
            while (lo < hi) {
                int mid = (lo + hi) >> 1;
                if (kk <= (long long)C[R[xb]] - C[R[xa]]) { xa = L[xa]; xb = L[xb]; hi = mid; }
                else { kk -= C[R[xb]] - C[R[xa]]; xa = R[xa]; xb = R[xb]; lo = mid + 1; }
            }
            long long m = qs[lo], cl = 0, sl = 0;
            int ya = roots[l], yb = roots[r + 1]; lo = 0; hi = V - 1;
            while (lo < hi) {
                int mid = (lo + hi) >> 1;
                if (m <= mid) { ya = L[ya]; yb = L[yb]; hi = mid; }
                else {
                    cl += C[L[yb]] - C[L[ya]]; sl += S[L[yb]] - S[L[ya]];
                    ya = R[ya]; yb = R[yb]; lo = mid + 1;
                }
            }
            cl += C[yb] - C[ya]; sl += S[yb] - S[ya];
            ans.push_back((int)(m * cl - sl + (stot - sl) - m * (tot - cl)));
        }
        return ans;
    }
};

