var minOperations = function(nums, k, queries) {
    const n = nums.length, res = nums.map(x => x % k);
    const mn = [res.slice()], mx = [res.slice()];
    for (let j = 1; (1 << j) <= n; j++) {
        const h = 1 << (j - 1), a = [], b = [];
        for (let i = 0; i + (1 << j) <= n; i++) {
            a.push(Math.min(mn[j-1][i], mn[j-1][i+h]));
            b.push(Math.max(mx[j-1][i], mx[j-1][i+h]));
        }
        mn.push(a); mx.push(b);
    }
    const vals = nums.map((x, i) => (x - res[i]) / k);
    const qs = [...new Set(vals)].sort((p, q) => p - q);
    const V = qs.length, idx = new Map(qs.map((v, i) => [v, i]));
    const L = [0], R = [0], C = [0], S = [0];
    function add(prev, lo, hi, p, v) {
        const node = L.length;
        L.push(L[prev]); R.push(R[prev]); C.push(C[prev] + 1); S.push(S[prev] + v);
        if (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (p <= mid) L[node] = add(L[prev], lo, mid, p, v);
            else R[node] = add(R[prev], mid + 1, hi, p, v);
        }
        return node;
    }
    const roots = [0];
    for (let i = 0; i < n; i++) roots.push(add(roots[i], 0, V - 1, idx.get(vals[i]), vals[i]));
    return queries.map(([l, r]) => {
        const jg = 31 - Math.clz32(r - l + 1);
        if (Math.min(mn[jg][l], mn[jg][r - (1 << jg) + 1]) !== Math.max(mx[jg][l], mx[jg][r - (1 << jg) + 1])) return -1;
        let A = roots[l], B = roots[r + 1];
        const tot = C[B] - C[A], stot = S[B] - S[A];
        let kk = (tot + 1) >> 1, lo = 0, hi = V - 1, xa = A, xb = B;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (kk <= C[R[xb]] - C[R[xa]]) { xa = L[xa]; xb = L[xb]; hi = mid; }
            else { kk -= C[R[xb]] - C[R[xa]]; xa = R[xa]; xb = R[xb]; lo = mid + 1; }
        }
        const m = qs[lo]; let cl = 0, sl = 0, ya = roots[l], yb = roots[r + 1]; lo = 0; hi = V - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (m <= mid) { ya = L[ya]; yb = L[yb]; hi = mid; }
            else {
                cl += C[L[yb]] - C[L[ya]]; sl += S[L[yb]] - S[L[ya]];
                ya = R[ya]; yb = R[yb]; lo = mid + 1;
            }
        }
        cl += C[yb] - C[ya]; sl += S[yb] - S[ya];
        return m * cl - sl + (stot - sl) - m * (tot - cl);
    });
};
